// 1. 定义统一的 Repository
@Singleton
class NoteRepository @Inject constructor(
    private val noteDao: NoteDao,
    private val noteApi: NoteApi,
    private val syncWorkManager: SyncWorkManager
) {
    // 离线优先：读取永远走本地
    fun observeNotes(): Flow<List<Note>> = noteDao.observeAll()

    // 写入先落本地，标记 dirty，触发后台同步
    suspend fun saveNote(note: Note) {
        noteDao.upsert(note.copy(isDirty = true, updatedAt = System.currentTimeMillis()))
        syncWorkManager.enqueueSync()
    }
}

// 2. Room Entity 带同步元数据
@Entity(tableName = "notes")
@Keep
data class Note(
    @PrimaryKey val id: String = UUID.randomUUID().toString(),
    val title: String,
    val content: String,
    val isDirty: Boolean = false,       // 本地有未同步的修改
    val isDeleted: Boolean = false,     // 软删除，同步后物理删除
    val updatedAt: Long = 0L,           // 用于冲突解决的逻辑时钟
    val serverVersion: Long = 0L        // 服务端版本号
)

// 3. WorkManager 后台同步
@HiltWorker
class SyncWorker @AssistedInject constructor(
    @Assisted ctx: Context,
    @Assisted params: WorkerParameters,
    private val noteDao: NoteDao,
    private val noteApi: NoteApi
) : CoroutineWorker(ctx, params) {

    override suspend fun doWork(): Result {
        // Step A: Push 本地脏数据
        val dirtyNotes = noteDao.getDirtyNotes()
        for (note in dirtyNotes) {
            try {
                val serverNote = noteApi.syncNote(note.toSyncDto())
                noteDao.upsert(note.copy(
                    isDirty = false,
                    serverVersion = serverNote.version
                ))
            } catch (e: HttpException) {
                if (e.code() == 409) {
                    // 冲突：服务端返回新版本，采用 Last-Write-Wins
                    val remote = noteApi.getNote(note.id)
                    val resolved = resolveConflict(note, remote)
                    noteDao.upsert(resolved)
                }
            }
        }
        // Step B: Pull 服务端变更
        val lastSync = prefs.getLastSyncTimestamp()
        val remoteChanges = noteApi.getChangesSince(lastSync)
        for (remote in remoteChanges) {
            val local = noteDao.getById(remote.id)
            if (local == null || !local.isDirty) {
                noteDao.upsert(remote.toLocal())
            } else {
                // 本地也有改动，冲突解决
                noteDao.upsert(resolveConflict(local, remote))
            }
        }
        prefs.setLastSyncTimestamp(System.currentTimeMillis())
        return Result.success()
    }

    // Last-Write-Wins + 字段级合并
    private fun resolveConflict(local: Note, remote: NoteRemoteDto): Note {
        return if (local.updatedAt > remote.updatedAt) {
            local.copy(isDirty = true) // 本地更新，重新推送
        } else {
            remote.toLocal().copy(isDirty = false)
        }
    }
}

// 示例 A：coroutineScope
suspend fun fetchDashboard() = coroutineScope {
    val user = async { fetchUser() }      // 假设成功
    val orders = async { fetchOrders() }   // 假设抛出 IOException
    // orders 失败 → coroutineScope 取消 user → 整个 scope 失败
    // fetchDashboard() 会抛出 IOException
}

// 示例 B：supervisorScope
suspend fun fetchDashboardSafe() = supervisorScope {
    val user = async { fetchUser() }       // 成功，不受影响
    val orders = async { fetchOrders() }   // 抛出 IOException
    // orders 失败 → 仅 orders 自身被取消
    // user 继续执行，supervisorScope 不会取消其他子协程
    // 但 orders 的异常在 await() 时仍然会抛出
}

// 实际使用：逐个处理结果
suspend fun fetchDashboardHandled() = supervisorScope {
    val userDeferred = async { fetchUser() }
    val ordersDeferred = async { fetchOrders() }

    val user = try { userDeferred.await() } catch (e: Exception) { null }
    val orders = try { ordersDeferred.await() } catch (e: Exception) { emptyList() }

    DashboardData(user = user ?: defaultUser(), orders = orders)
}
